mapper.select:
SELECT fr.REPORT_ID as reportId, fr.REPORT_CODE as reportCode, fr.REPORT_NAME as reportName, CASE fr.REPORT_TYPE WHEN 1 THEN '资产负债表' WHEN 2 THEN '利润表' WHEN 3 THEN '现金流量表' ELSE '其他' END as reportTypeName, fr.REPORT_TYPE as reportType, fr.REPORT_PERIOD as reportPeriod, CASE fr.REPORT_STATUS WHEN 1 THEN '草稿' WHEN 2 THEN '已生成' WHEN 3 THEN '已审核' ELSE '未知' END as reportStatusName, fr.REPORT_STATUS as reportStatus, fr.GENERATE_TIME as generateTime, fr.CREATE_TIME as createTime, s.STAFFNAME as creatorName FROM T_FINANCIAL_REPORT fr LEFT JOIN TBL_STAFF s ON fr.CREATOR = s.STAFFID WHERE fr.IS_DELETED = 0
AND fr.REPORT_CODE LIKE '%' || #{param.reportCode} || '%'
AND fr.REPORT_NAME LIKE '%' || #{param.reportName} || '%'
AND fr.REPORT_TYPE = #{param.reportType}
AND fr.REPORT_PERIOD = #{param.reportPeriod}
AND fr.REPORT_STATUS = #{param.reportStatus}
AND fr.BOOK_ID = #{param.bookId}
AND fr.TENANT_ID = #{param.tenantId}
ORDER BY fr.CREATE_TIME DESC

SELECT
    COUNT(*) as totalReports,
    SUM(CASE WHEN REPORT_STATUS = 2 THEN 1 ELSE 0 END) as generatedReports,
    SUM(CASE WHEN REPORT_STATUS = 1 THEN 1 ELSE 0 END) as draftReports,
    SUM(CASE WHEN REPORT_STATUS = 3 THEN 1 ELSE 0 END) as reviewedReports,
    COUNT(DISTINCT REPORT_TYPE) as reportTypes,
    COUNT(DISTINCT REPORT_PERIOD) as reportPeriods
FROM T_FINANCIAL_REPORT
WHERE IS_DELETED = 0

    AND BOOK_ID = #{param.bookId}


    AND TENANT_ID = #{param.tenantId}


    AND REPORT_PERIOD >= #{param.startPeriod}


    AND REPORT_PERIOD <= #{param.endPeriod}

SELECT COUNT(*)
FROM T_FINANCIAL_REPORT
WHERE REPORT_CODE = #{reportCode}
  AND BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}
  AND IS_DELETED = 0

    AND REPORT_ID != #{reportId}
